847: /* Utility function to get the fragmentation ratio from jemalloc.
848:  * It is critical to do that by comparing only heap maps that belong to
849:  * jemalloc, and skip ones the jemalloc keeps as spare. Since we use this
850:  * fragmentation ratio in order to decide if a defrag action should be taken
851:  * or not, a false detection can cause the defragmenter to waste a lot of CPU
852:  * without the possibility of getting any results. */
853: float getAllocatorFragmentation(size_t *out_frag_bytes) {
854:     size_t resident, active, allocated, frag_smallbins_bytes;
855:     zmalloc_get_allocator_info(1, &allocated, &active, &resident, NULL, NULL, &frag_smallbins_bytes);
856: 
857:     if (server.lua_arena != UINT_MAX) {
858:         size_t lua_resident, lua_active, lua_allocated, lua_frag_smallbins_bytes;
859:         zmalloc_get_allocator_info_by_arena(server.lua_arena, 0, &lua_allocated, &lua_active, &lua_resident, &lua_frag_smallbins_bytes);
860:         resident -= lua_resident;
861:         active -= lua_active;
862:         allocated -= lua_allocated;
863:         frag_smallbins_bytes -= lua_frag_smallbins_bytes;
864:     }
865: 
866:     /* Calculate the fragmentation ratio as the proportion of wasted memory in small
867:      * bins (which are defraggable) relative to the total allocated memory (including large bins).
868:      * This is because otherwise, if most of the memory usage is large bins, we may show high percentage,
869:      * despite the fact it's not a lot of memory for the user. */
870:     float frag_pct = (float)frag_smallbins_bytes / allocated * 100;
871:     float rss_pct = ((float)resident / allocated)*100 - 100;
872:     size_t rss_bytes = resident - allocated;
873:     if(out_frag_bytes)
874:         *out_frag_bytes = frag_smallbins_bytes;
875:     serverLog(LL_DEBUG,
876:         "allocated=%zu, active=%zu, resident=%zu, frag=%.2f%% (%.2f%% rss), frag_bytes=%zu (%zu rss)",
877:         allocated, active, resident, frag_pct, rss_pct, frag_smallbins_bytes, rss_bytes);
878:     return frag_pct;
879: }
