418: void dismissSetObject(robj *o, size_t size_hint) {
419:     if (o->encoding == OBJ_ENCODING_HT) {
420:         dict *set = o->ptr;
421:         serverAssert(dictSize(set) != 0);
422:         /* We iterate all nodes only when average member size is bigger than a
423:          * page size, and there's a high chance we'll actually dismiss something. */
424:         if (size_hint / dictSize(set) >= server.page_size) {
425:             dictEntry *de;
426:             dictIterator *di = dictGetIterator(set);
427:             while ((de = dictNext(di)) != NULL) {
428:                 dismissSds(dictGetKey(de));
