523: /* When creating a snapshot in a fork child process, the main process and child
524:  * process share the same physical memory pages, and if / when the parent
525:  * modifies any keys due to write traffic, it'll cause CoW which consume
526:  * physical memory. In the child process, after serializing the key and value,
527:  * the data is definitely not accessed again, so to avoid unnecessary CoW, we
528:  * try to release their memory back to OS. see dismissMemory().
529:  *
530:  * Because of the cost of iterating all node/field/member/entry of complex data
531:  * types, we iterate and dismiss them only when approximate average we estimate
532:  * the size of an individual allocation is more than a page size of OS.
533:  * 'size_hint' is the size of serialized value. This method is not accurate, but
534:  * it can reduce unnecessary iteration for complex data types that are probably
535:  * not going to release any memory. */
536: void dismissObject(robj *o, size_t size_hint) {
537:     /* madvise(MADV_DONTNEED) may not work if Transparent Huge Pages is enabled. */
538:     if (server.thp_enabled) return;
539: 
540:     /* Currently we use zmadvise_dontneed only when we use jemalloc with Linux.
541:      * so we avoid these pointless loops when they're not going to do anything. */
542: #if defined(USE_JEMALLOC) && defined(__linux__)
543:     if (o->refcount != 1) return;
544:     switch(o->type) {
545:         case OBJ_STRING: dismissStringObject(o); break;
546:         case OBJ_LIST: dismissListObject(o, size_hint); break;
547:         case OBJ_SET: dismissSetObject(o, size_hint); break;
548:         case OBJ_ZSET: dismissZsetObject(o, size_hint); break;
549:         case OBJ_HASH: dismissHashObject(o, size_hint); break;
550:         case OBJ_STREAM: dismissStreamObject(o, size_hint); break;"}

