130: /* This function loads a time from the RDB file. It gets the version of the
131:  * RDB because, unfortunately, before Redis 5 (RDB version 9), the function
132:  * failed to convert data to/from little endian, so RDB files with keys having
133:  * expires could not be shared between big endian and little endian systems
134:  * (because the expire time will be totally wrong). The fix for this is just
135:  * to call memrev64ifbe(), however if we fix this for all the RDB versions,
136:  * this call will introduce an incompatibility for big endian systems:
137:  * after upgrading to Redis version 5 they will no longer be able to load their
138:  * own old RDB files. Because of that, we instead fix the function only for new
139:  * RDB versions, and load older RDB versions as we used to do in the past,
140:  * allowing big endian systems to load their own old RDB files.
141:  *
142:  * On I/O error the function returns LLONG_MAX, however if this is also a
143:  * valid stored value, the caller should use rioGetReadError() to check for
144:  * errors after calling this function. */
145: long long rdbLoadMillisecondTime(rio *rdb, int rdbver) {
146:     int64_t t64;
147:     if (rioRead(rdb,&t64,8) == 0) return LLONG_MAX;
148:     if (rdbver >= 9) /* Check the top comment of this function. */
149:         memrev64ifbe(&t64); /* Convert in big endian if the system is BE. */
150:     return (long long)t64;"}

